window.homeForceDownloadAssets={"homeforce-app-icon-512.png":{"type":"image/png","data":""},"homeforce-favicon-48.png":{"type":"image/png","data":""},"homeforce-favicon.ico":{"type":"image/x-icon","data":""},"homeforce-favicon.svg":{"type":"image/svg+xml","data":""},"homeforce-logo-actual.png":{"type":"image/png","data":""},"homeforce-logo-black-transparent.png":{"type":"image/png","data":""},"homeforce-logo-black.eps":{"type":"application/postscript","data":""},"homeforce-logo-black.svg":{"type":"image/svg+xml","data":""},"homeforce-logo-color-transparent.png":{"type":"image/png","data":""},"homeforce-logo-dark-mode.png":{"type":"image/png","data":""},"homeforce-logo-master.eps":{"type":"application/postscript","data":""},"homeforce-logo-master.svg":{"type":"image/svg+xml","data":""},"homeforce-logo-white-transparent.png":{"type":"image/png","data":""}};
document.querySelectorAll('a[download][href]').forEach(link=>link.addEventListener('click',event=>{const key=decodeURIComponent(link.getAttribute('href').split(/[?#]/)[0].split('/').pop());const asset=window.homeForceDownloadAssets[key];if(!asset)return;try{const binary=atob(asset.data);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const blob=new Blob([bytes],{type:asset.type});const objectUrl=URL.createObjectURL(blob);const save=document.createElement('a');save.href=objectUrl;save.download=link.getAttribute('download')||key;save.style.display='none';document.body.appendChild(save);event.preventDefault();save.click();save.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),30000)}catch(error){console.error('HomeForce asset download failed:',error)}}));